// Extract the tool_use payload and validate it against the lead_qualification schema.
// This is the reliability contract: no partially-shaped object ever reaches the CRM.
const schema = $vars.LEAD_SCHEMA; // JSON Schema (see claude/schema.json)
const res = $input.first().json;
let obj = null;
try {
  const block = (res.content || []).find(c => c.type === 'tool_use' && c.name === 'lead_qualification');
  obj = block ? block.input : null;
} catch (e) { obj = null; }

function validate(o) {
  const errs = [];
  if (!o || typeof o !== 'object') return ['no object returned'];
  const req = schema.schema.required;
  for (const k of req) if (!(k in o)) errs.push(`missing ${k}`);
  if (o.score < 0 || o.score > 100) errs.push('score out of range');
  if (!['hot','warm','cold'].includes(o.intent)) errs.push('bad intent enum');
  if (typeof o.is_spam !== 'boolean') errs.push('is_spam not boolean');
  if (!['new-hot','new-warm','nurture','disqualified'].includes(o.pipeline_stage)) errs.push('bad pipeline_stage');
  if (o.confidence < 0 || o.confidence > 1) errs.push('confidence out of range');
  return errs;
}

const errors = validate(obj);
return [{ json: { valid: errors.length === 0, errors, qualification: obj } }];

